package main

import (
	_ "embed"
	"encoding/json"
	"strings"
)

// Fonts the app ships with (frontend/public/fonts/, served at /fonts/), for
// the book's "Fonts and licenses" list (fontlicense.go) and the line-metrics
// endpoint (fontmetrics.go). The registry is bundledfonts.json, generated by
// scripts/fetch-fonts.mjs from Google's own metadata; the map's key is the
// lower-case family name.

type bundledFont struct {
	License    string       `json:"license"` // "OFL-1.1" or "Apache-2.0"
	Copyright  string       `json:"copyright"`
	LicenseURL string       `json:"license_url"`
	Designer   string       `json:"designer"`
	Metrics    *lineMetrics `json:"metrics,omitempty"`
}

//go:embed bundledfonts.json
var bundledFontsJSON []byte

var bundledFonts = map[string]bundledFont{}

func init() {
	var raw map[string]bundledFont
	if err := json.Unmarshal(bundledFontsJSON, &raw); err != nil {
		panic("bundledfonts.json: " + err.Error())
	}
	for k, v := range raw {
		bundledFonts[strings.ToLower(k)] = v
	}
}
